// Reads the raw request body (the signature covers the exact bytes) and splits
// the `t=<unix>,v1=<hex>` header. The HMAC itself is computed by the next node.
const item = $input.first();
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const header = String(item.json.headers?.['x-lendloop-signature'] ?? '');
const parts = Object.fromEntries(
  header.split(',').map((p) => {
    const i = p.indexOf('=');
    return [p.slice(0, i).trim(), p.slice(i + 1).trim()];
  }),
);
return [
  {
    json: {
      raw,
      header,
      t: parts.t ?? '',
      v1: parts.v1 ?? '',
      message: `${parts.t}.${raw}`,
      secretConfigured: Boolean($env.N8N_WEBHOOK_SECRET),
    },
  },
];

// Decides whether the webhook call is authentic. Fails closed on every doubt.
const { raw, header, t, v1, expected, secretConfigured } = $input.first().json;

// Constant-time comparison so timing does not leak how many characters matched.
function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

let reason = '';
if (!secretConfigured) reason = 'server not configured';
else if (!header) reason = 'missing';
else if (!t || !v1 || Number.isNaN(Number(t))) reason = 'malformed';
else if (Math.abs(Date.now() / 1000 - Number(t)) > 300) reason = 'expired';
else if (!safeEqual(String(expected), v1)) reason = 'mismatch';

let payload = null;
if (!reason) {
  try {
    payload = JSON.parse(raw);
  } catch {
    reason = 'bad json';
  }
}
// The payload is only passed on when the signature checked out.
return [{ json: { valid: reason === '', reason, payload } }];

// Builds the message from the minimal payload and checks whether this event was
// already delivered. Convex retries on timeouts, so duplicates can happen.
const p = $json.payload;
const store = $getWorkflowStaticData('global');
const alreadySent = Boolean(store.delivered && store.delivered[p.eventId]);

const oneLine = (s) => String(s ?? '').replace(/[\r\n]+/g, ' ').slice(0, 120);
const tool = oneLine(p.toolName);
const to = p.recipient;
const other = oneLine(p.otherParty?.name);
const dates = `${p.startDate} to ${p.endDate}`;

const copy = {
  'loan.requested': [`New request for your ${tool}`, `${other} would like to borrow your ${tool} (${dates}). Open LendLoop to approve or decline.`],
  'loan.approved': [`${tool}: request approved`, `${other} approved your request to borrow the ${tool} (${dates}). Please return it on time.`],
  'loan.declined': [`${tool}: request declined`, `${other} could not lend the ${tool} for ${dates}. Other tools may be available on LendLoop.`],
  'loan.cancelled': [`${tool}: request withdrawn`, `${other} withdrew their request for your ${tool} (${dates}). No action needed.`],
  'loan.returned': [`${tool}: marked as returned`, `${other} marked the ${tool} as returned. Thank you for using LendLoop.`],
}[p.type];
if (!copy) throw new Error(`Unknown event type: ${oneLine(p.type)}`);

return [
  {
    json: {
      eventId: p.eventId,
      alreadySent,
      to: to.email,
      subject: copy[0],
      text: `Hi ${oneLine(to.name)},\n\n${copy[1]}\n\nLendLoop`,
    },
  },
];

// Runs after "Respond 502" has already told Convex the delivery failed (so Convex
// retries). Throwing here fails the execution, which starts the error workflow and
// records the failure in Convex for admins to see.
const reason = typeof $json.error === 'string' ? $json.error : $json.error?.message;
throw new Error(`Notification delivery failed: ${reason ?? 'unknown error'}`);

// NOTIFY_CHANNEL=log: write the message to the n8n log instead of sending mail.
// Only the recipient's address and subject are logged, never the body.
console.log(`[lendloop] notification to ${$json.to}: ${$json.subject}`);
return [{ json: { ...$json, delivered: 'logged' } }];

// Records the event as delivered. This runs only after the send succeeded, so a
// failed send is retried by Convex instead of being dropped as a duplicate.
const { eventId } = $('Dedupe and render').first().json;
const store = $getWorkflowStaticData('global');
store.delivered = store.delivered || {};
store.delivered[eventId] = Date.now();

// Keep the list small: drop the oldest entries beyond 500.
const ids = Object.keys(store.delivered);
if (ids.length > 500) {
  ids
    .sort((a, b) => store.delivered[a] - store.delivered[b])
    .slice(0, ids.length - 500)
    .forEach((id) => delete store.delivered[id]);
}
return [{ json: { eventId } }];
